import { damp } from 'maath/easing';
import {
    LinearFilter,
    Mesh,
    NoColorSpace,
    OrthographicCamera,
    PlaneGeometry,
    Scene,
    ShaderMaterial,
    Timer,
    Vector2,
    VideoFrameTexture,
    WebGLRenderer,
} from 'three';
import { Pane } from 'tweakpane';
import { ActiveFramePlayer } from './ActiveFramePlayer';

// Generated by scripts/video-flow/build.sh (see README.md next to this file).
const COLOR_SRC = '/static/videos/video-flow-scrub/underwater2_color.af';
const FLOW_SRC = '/static/videos/video-flow-scrub/underwater2_flow.af';

const MODES = { none: 0, crossfade: 1, flow: 2 } as const;

type Mode = keyof typeof MODES;

type FlowMeta = {
    width: number;
    height: number;
    cellHeight: number;
    atlasWidth: number;
    atlasHeight: number;
    scales: number[];
};

const VERTEX_SHADER = /* glsl */ `
varying vec2 vUv;

void main() {
    vUv = uv;
    gl_Position = vec4(position.xy, 0., 1.);
}
`;

const FRAGMENT_SHADER = /* glsl */ `
varying vec2 vUv;

uniform sampler2D uFrameA;
uniform sampler2D uFrameB;
uniform sampler2D uFlow;
uniform float uT;
uniform int uMode;
uniform bool uOcclusion;
uniform float uFlowScale;
uniform vec2 uFlowSize;
uniform vec2 uCellUvScale;
uniform vec2 uCoverScale;

// Flow atlas (image rows, top to bottom): [fwd.x | fwd.y] then [bwd.x | bwd.y], 8-bit, 127.5 = 0.
// fwd maps frame A -> B, bwd maps B -> A, both in flow-resolution pixels, y down.
vec2 sampleFlow(vec2 uv, float row) {
    vec2 halfTexel = 0.5 / uFlowSize;
    vec2 p = clamp(vec2(uv.x, 1. - uv.y), halfTexel, 1. - halfTexel);
    float v = 1. - (row + p.y * uCellUvScale.y);
    float x = texture2D(uFlow, vec2(p.x * 0.5, v)).r;
    float y = texture2D(uFlow, vec2(0.5 + p.x * 0.5, v)).r;
    vec2 px = (vec2(x, y) * 255. - 127.5) / 127.5 * uFlowScale;

    // pixels (y down) -> uv (y up)
    return vec2(px.x, -px.y) / uFlowSize;
}

vec2 fwdFlow(vec2 uv) { return sampleFlow(uv, 0.); }
vec2 bwdFlow(vec2 uv) { return sampleFlow(uv, uCellUvScale.x); }

void main() {
    vec2 uv = (vUv - 0.5) * uCoverScale + 0.5;
    vec4 a = texture2D(uFrameA, uv);
    vec4 b = texture2D(uFrameB, uv);
    float t = uT;

    if (uMode == 0) {
        gl_FragColor = t < 0.5 ? a : b;
    } else if (uMode == 1) {
        gl_FragColor = mix(a, b, t);
    } else {
        vec2 f01 = fwdFlow(uv);
        vec2 f10 = bwdFlow(uv);
        // intermediate flows t->0 and t->1 from both directions (Super SloMo approximation)
        vec2 ft0 = -(1. - t) * t * f01 + t * t * f10;
        vec2 ft1 = (1. - t) * (1. - t) * f01 - t * (1. - t) * f10;
        vec2 uvA = uv + ft0;
        vec2 uvB = uv + ft1;
        float wA = 1. - t;
        float wB = t;

        if (uOcclusion) {
            // forward/backward consistency at the sampled points; inconsistent = likely occluded
            vec2 qa = fwdFlow(uvA);
            vec2 qb = bwdFlow(uvB);
            float eA = length((qa + bwdFlow(uvA + qa)) * uFlowSize);
            float eB = length((qb + fwdFlow(uvB + qb)) * uFlowSize);
            wA *= exp(-eA * eA / 16.);
            wB *= exp(-eB * eB / 16.);
            wA += 1e-4;
            wB += 1e-4;
        }

        gl_FragColor = (texture2D(uFrameA, uvA) * wA + texture2D(uFrameB, uvB) * wB) / (wA + wB);
    }

}
`;

type Stream = {
    player: ActiveFramePlayer;
    texture: VideoFrameTexture;
    pending?: { frame: VideoFrame; index: number };
    shown?: VideoFrame;
    offset: number;
};

class VideoFlowScrubDemo {
    private readonly canvas: HTMLCanvasElement;
    private readonly renderer: WebGLRenderer;
    private readonly scene = new Scene();
    private readonly camera = new OrthographicCamera(-1, 1, 1, -1, 0, 1);
    private readonly timer = new Timer();
    private readonly material: ShaderMaterial;
    private readonly mesh: Mesh;
    private readonly streams: Stream[];
    private readonly scrollEl: HTMLDivElement;
    private pane?: Pane;
    private disposed = false;
    private totalFrames = 0;
    private flowMeta?: FlowMeta;
    private rawProgress = 0;
    private shownIndex = -1;
    private videoAspect = 16 / 9;

    params = {
        mode: 'flow' as Mode,
        occlusion: false,
        smoothing: 0.15,
        position: 0,
    };

    private readonly scrollState = { position: 0 };

    constructor(canvas: HTMLCanvasElement) {
        this.canvas = canvas;
        this.onResize = this.onResize.bind(this);
        this.onScroll = this.onScroll.bind(this);

        this.renderer = new WebGLRenderer({ canvas, antialias: false, powerPreference: 'high-performance' });

        const makeTexture = () => {
            const texture = new VideoFrameTexture();

            // everything stays in display (video) space: three uploads video textures as RGBA8 without
            // sRGB decode, so an output colorspace encode in this raw shader would brighten the video
            texture.colorSpace = NoColorSpace;
            texture.minFilter = LinearFilter;
            texture.magFilter = LinearFilter;
            texture.generateMipmaps = false;

            return texture;
        };

        // A = frame i, B = frame i + 1, flow = pair i. Two decoders on the same color file avoid
        // re-decoding a GOP every time the pair moves.
        this.streams = [
            { url: COLOR_SRC, offset: 0 },
            { url: COLOR_SRC, offset: 1 },
            { url: FLOW_SRC, offset: 0 },
        ].map(({ url, offset }) => {
            const stream: Stream = {
                texture: makeTexture(),
                offset,
                player: new ActiveFramePlayer(url, (frame, index) => {
                    stream.pending?.frame.close();
                    stream.pending = { frame, index };
                }),
            };

            return stream;
        });

        this.material = new ShaderMaterial({
            vertexShader: VERTEX_SHADER,
            fragmentShader: FRAGMENT_SHADER,
            uniforms: {
                uFrameA: { value: this.streams[0].texture },
                uFrameB: { value: this.streams[1].texture },
                uFlow: { value: this.streams[2].texture },
                uT: { value: 0 },
                uMode: { value: MODES.flow },
                uOcclusion: { value: false },
                uFlowScale: { value: 0 },
                uFlowSize: { value: new Vector2(960, 540) },
                uCellUvScale: { value: new Vector2(0.5, 0.5) },
                uCoverScale: { value: new Vector2(1, 1) },
            },
        });
        this.mesh = new Mesh(new PlaneGeometry(2, 2), this.material);
        this.mesh.visible = false;
        this.scene.add(this.mesh);

        this.scrollEl = this.createScrollDom();
        window.addEventListener('resize', this.onResize);
        this.onResize();

        void this.init();
        this.renderer.setAnimationLoop(() => this.renderFrame());
    }

    private createScrollDom() {
        const el = document.createElement('div');

        el.className = 'video-flow-scrub__scroll';
        Object.assign(el.style, {
            position: 'absolute',
            inset: '0',
            overflowY: 'auto',
            overflowX: 'hidden',
            touchAction: 'pan-y',
        });

        const fill = document.createElement('div');

        // ponytail: fixed scroll length (~6 screens), not tied to frame count
        fill.style.height = '600%';
        fill.style.pointerEvents = 'none';
        el.appendChild(fill);
        el.addEventListener('scroll', this.onScroll, { passive: true });
        this.canvas.parentElement?.appendChild(el);

        return el;
    }

    private onScroll() {
        const max = this.scrollEl.scrollHeight - this.scrollEl.clientHeight;

        this.rawProgress = max > 0 ? this.scrollEl.scrollTop / max : 0;
    }

    private async init() {
        try {
            if (typeof VideoDecoder === 'undefined') throw new Error('WebCodecs VideoDecoder is not available');

            await Promise.all(this.streams.map((s) => s.player.init()));
        } catch (error) {
            // eslint-disable-next-line no-console
            console.error('[video-flow-scrub]', error);

            return;
        }

        if (this.disposed) return;

        const color = this.streams[0].player.manifest;
        const flow = this.streams[2].player.manifest;

        this.flowMeta = flow.flow as FlowMeta;
        this.totalFrames = color.totalFrames;
        this.videoAspect = color.width / color.height;

        if (flow.totalFrames !== color.totalFrames) {
            // eslint-disable-next-line no-console
            console.error('[video-flow-scrub] color and flow .af are out of sync');

            return;
        }

        const meta = this.flowMeta;

        this.material.uniforms.uFlowSize.value.set(meta.width, meta.height);
        // x: row offset of the backward cells, y: one cell's height, both in atlas uv
        this.material.uniforms.uCellUvScale.value.set(
            meta.cellHeight / meta.atlasHeight,
            meta.height / meta.atlasHeight,
        );
        this.onResize();
        this.initPane();
    }

    private initPane() {
        this.pane = new Pane({ title: 'Parameters', expanded: matchMedia('(min-width: 1200px)').matches });
        this.pane.addBinding(this.params, 'mode', {
            options: { 'No interpolation': 'none', Crossfade: 'crossfade', 'Optical flow': 'flow' },
        });
        this.pane.addBinding(this.params, 'occlusion', { label: 'occlusion weights' });
        this.pane.addBinding(this.params, 'smoothing', { min: 0, max: 0.6, step: 0.01 });
        this.pane.addBinding(this.params, 'position', {
            readonly: true,
            label: 'frame',
            format: (v: number) => v.toFixed(3),
        });
    }

    /** Swap in a new pair only when A, B and flow all belong to it, so the shader never mixes pairs. */
    private commitPending() {
        const [a, b, f] = this.streams;

        if (!a.pending || !b.pending || !f.pending) return;

        const index = a.pending.index;

        if (b.pending.index !== Math.min(index + 1, this.totalFrames - 1) || f.pending.index !== index) return;

        for (const s of this.streams) {
            s.texture.setFrame(s.pending!.frame);
            s.shown?.close();
            s.shown = s.pending!.frame;
            s.pending = undefined;
        }

        this.shownIndex = index;
        this.material.uniforms.uFlowScale.value = this.flowMeta?.scales[index] ?? 0;
        this.mesh.visible = true;
    }

    private renderFrame() {
        this.timer.update();
        const delta = this.timer.getDelta();

        if (!this.totalFrames) return;

        const last = this.totalFrames - 1;
        const target = this.rawProgress * last;

        if (this.params.smoothing > 0) {
            damp(this.scrollState, 'position', target, this.params.smoothing, delta, Infinity, undefined, 1e-4);
        } else {
            this.scrollState.position = target;
        }

        const position = Math.min(Math.max(this.scrollState.position, 0), last);
        const index = Math.min(Math.floor(position), last - 1);

        this.params.position = position;

        for (const s of this.streams) s.player.setFrame(index + s.offset);

        this.commitPending();

        if (this.shownIndex < 0) return;

        // t is relative to the pair on screen; while the next pair decodes this clamps to its end frame
        this.material.uniforms.uT.value = Math.min(Math.max(position - this.shownIndex, 0), 1);
        this.material.uniforms.uMode.value = MODES[this.params.mode];
        this.material.uniforms.uOcclusion.value = this.params.occlusion;

        this.renderer.render(this.scene, this.camera);
    }

    private onResize() {
        const width = this.canvas.parentElement?.offsetWidth || 1;
        const height = this.canvas.parentElement?.offsetHeight || 1;
        const aspect = width / height;

        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        this.renderer.setSize(width, height);
        // cover: crop the video instead of letterboxing
        this.material.uniforms.uCoverScale.value.set(
            Math.min(aspect / this.videoAspect, 1),
            Math.min(this.videoAspect / aspect, 1),
        );
        this.onScroll();
    }

    destroy() {
        this.disposed = true;
        this.renderer.setAnimationLoop(null);
        window.removeEventListener('resize', this.onResize);
        this.scrollEl.removeEventListener('scroll', this.onScroll);
        this.scrollEl.remove();
        this.pane?.dispose();

        for (const s of this.streams) {
            s.player.destroy();
            s.pending?.frame.close();
            s.shown?.close();
            s.texture.dispose();
        }

        this.mesh.geometry.dispose();
        this.material.dispose();
        this.renderer.dispose();
    }
}

export default VideoFlowScrubDemo;
